/**
 * PSE Sectors Provider
 *
 * Reads data/pse-sectors.json (generated by scripts/scrape-pse-sectors.ts,
 * which scrapes real sector/subsector data from PSE Edge's company directory
 * at https://edge.pse.com.ph/companyDirectory/search.ax). The directory
 * covers all ~282 PSE-listed common-stock companies with their official PSE
 * sector and subsector classification — the same six-sector grouping used
 * for the PSEi-30 in PSE_SECTORS, but for the full universe.
 *
 * Unlike pseFundamentalsProvider.ts, there is no synthetic fallback here —
 * a missing sector is left as `null` rather than guessed, and the UI
 * renders "—" (same honest pattern as before, just now backed by real data
 * for all 282 companies instead of only the PSEi-30).
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

export interface RealPseSectorRecord {
  symbol: string;
  companyName: string;
  sector: string;
  subsector: string;
  cmpyId: number | null;
  /** PSE Edge listing date, e.g. "Mar 22, 1973". Absent in older scrapes. */
  listingDate?: string | null;
  sourceUrl: string;
}

type RealSectorMap = Record<string, RealPseSectorRecord>;

let realSectorCache: RealSectorMap | null = null;

function loadRealSectorMap(): RealSectorMap {
  if (realSectorCache !== null) return realSectorCache;
  let loaded: RealSectorMap = {};
  try {
    const raw = readFileSync(resolve(process.cwd(), 'data/pse-sectors.json'), 'utf-8');
    loaded = JSON.parse(raw).results ?? {};
  } catch {
    // File not generated yet (scripts/scrape-pse-sectors.ts hasn't been
    // run) — treat as "no real data available", not an error.
  }
  realSectorCache = loaded;
  return loaded;
}

/** Real sector record for a symbol, or null if none is available.
 * Never fabricates a fallback — callers should render nothing rather
 * than a guessed sector. */
export function loadPseSector(symbol: string): RealPseSectorRecord | null {
  const record = loadRealSectorMap()[symbol.toUpperCase()];
  if (!record || !record.sector) return null;
  return record;
}

/** Returns the PSE sector name for a symbol (e.g. "Financials"), or null. */
export function getSectorBySymbol(symbol: string): string | null {
  const record = loadPseSector(symbol);
  return record?.sector ?? null;
}

/** Returns the PSE subsector name for a symbol (e.g. "Banks"), or null. */
export function getSubsectorBySymbol(symbol: string): string | null {
  const record = loadPseSector(symbol);
  return record?.subsector ?? null;
}

/** Returns a Map of symbol → sector for all companies in the data file. */
export function getAllPseSectors(): Map<string, string> {
  const map = new Map<string, string>();
  const records = loadRealSectorMap();
  for (const [symbol, record] of Object.entries(records)) {
    if (record.sector) {
      map.set(symbol, record.sector);
    }
  }
  return map;
}
